import React, { useState, useEffect } from 'react'; // Add useEffect
import DatePicker from 'react-datepicker';
import "react-datepicker/dist/react-datepicker.css";
import { useGlobalContext } from '../../context/globalContext';
import Button from '../Button/Button';
import { plus } from '../../utils/Icons';
import './Form.css';

function Form() {
    const { addIncome, error, setError } = useGlobalContext();

    const [inputState, setInputState] = useState({
        title: '',
        amount: '',
        date: '',
        category: '',
        description: '',
    });

    const [successMessage, setSuccessMessage] = useState(null);

    const { title, amount, date, category, description } = inputState;

    // Add this useEffect for error message timeout
    useEffect(() => {
        if (error) {
            const timer = setTimeout(() => {
                setError('');
            }, 3000); // 3 seconds
            return () => clearTimeout(timer); // Clear the timer if the component unmounts or error changes
        }
    }, [error, setError]);

    // Add this useEffect for success message timeout
    useEffect(() => {
        if (successMessage) {
            const timer = setTimeout(() => {
                setSuccessMessage(null);
            }, 3000); // 3 seconds
            return () => clearTimeout(timer); // Clear the timer if the component unmounts or successMessage changes
        }
    }, [successMessage]);

    const handleInput = (name) => (e) => {
        setInputState({ ...inputState, [name]: e.target.value });
        setError(''); // Clear error on input change
        setSuccessMessage(null); // Clear success message on input change
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const result = await addIncome(inputState);

        if (result.success) {
            setInputState({
                title: '',
                amount: '',
                date: '',
                category: '',
                description: '',
            });
            setSuccessMessage(result.message); // Set success message
        } else {
            setError(result.message); // Set error message
        }
    };

    return (
        <form className="form-container" onSubmit={handleSubmit}>
            {successMessage && <p className='success'>{successMessage}</p>}
            {error && <p className='error'>{error}</p>}

            {/* Rest of your form JSX remains the same */}
        </form>
    );
}

export default Form;
